//npm install js-md5 crypto-js  # MD5 或 HMAC-SHA256 可选
import md5 from "js-md5";
// npm install crypto-js --save  #安装 crypto-js 依赖（必选）
// # 或
// yarn add crypto-js
import CryptoJS from "crypto-js";

export default {
  // AES-256-CBC 加密
  encrypt(data, key, iv) {
    const utf8Key = CryptoJS.enc.Utf8.parse(key);
    const utf8IV = CryptoJS.enc.Utf8.parse(iv);
    return CryptoJS.AES.encrypt(data, utf8Key, {
      iv: utf8IV,
      mode: CryptoJS.mode.CBC,
      padding: CryptoJS.pad.Pkcs7,
    }).toString();
  },

  // AES-256-CBC 解密
  decrypt(ciphertext, key, iv) {
    const utf8Key = CryptoJS.enc.Utf8.parse(key);
    const utf8IV = CryptoJS.enc.Utf8.parse(iv);
    return CryptoJS.AES.decrypt(ciphertext, utf8Key, {
      iv: utf8IV,
      mode: CryptoJS.mode.CBC,
      padding: CryptoJS.pad.Pkcs7,
    }).toString(CryptoJS.enc.Utf8);
  },
  //增加加密验证
  decryptAndVerify(ciphertext, key) {
    const rawData = CryptoJS.enc.Base64.parse(ciphertext);
    const iv = rawData.slice(0, 16);
    const encrypted = rawData.slice(16, -64);
    const signature = rawData.slice(-64).toString();

    // 解密
    const decrypted = CryptoJS.AES.decrypt({ ciphertext: encrypted }, key, {
      iv,
    });

    // 验签
    const localSignature = CryptoJS.HmacSHA256(encrypted, key).toString();
    if (localSignature !== signature) throw new Error("签名无效");
    return decrypted.toString(CryptoJS.enc.Utf8);
  },
  // 动态生成随机IV
  generateIV() {
    return CryptoJS.lib.WordArray.random(16).toString();
  },
  // 基础签名生成（MD5）
  generateMD5Signature(params, secretKey) {
    const sortedParams = Object.keys(params)
      .sort()
      .map((k) => `${k}=${params[k]}`)
      .join("&");
    return md5(sortedParams + secretKey);
  },
  // HMAC-SHA256 签名（安全性更高）
  generateHMACSignature(params, secretKey) {
    const sortedStr = Object.keys(params)
      .sort()
      .map((k) => `${k}=${params[k]}`)
      .join("&");
    return CryptoJS.HmacSHA256(sortedStr, secretKey).toString(CryptoJS.enc.Hex);
  },
};
