// Vue 组件
<template>
    <div>
        <input v-model="name" placeholder="输入明文">
        <input v-model="inputText" placeholder="输入明文">
        <button @click="encryptData">加密并验证</button>
        <p>解密结果: {{ decryptedText }}</p>
    </div>
</template>

<script>
import crypto from '@/utils/crypto'

export default {
    data() {
        return {
            name: [],
            inputText: '',
            decryptedText: '',
            key: 'thisIs32BytesKeyForAES256CBCMode',
            iv: 'LQ33SL2G7dsiJee1mTimNw=='
        }
    },
    methods: {

        async encryptData() {
            //this.iv = crypto.generateIV();
            const encrypted = crypto.encrypt(this.inputText, this.key, this.iv)
            const encrtyname = crypto.encrypt(this.name, this.key, this.iv);
            try {
                const response = await this.$request({
                    method: 'post',
                    url: 'http://www.tp8.com/api/music/test',
                    data: {
                        firstName: encrypted,
                        lastName: encrtyname
                    }
                });
                const data = response.data;
                console.log(data)
            } catch (error) {
                if (error.name === 'SyntaxError') {
                    console.error('JSON 格式错误:', error.message);
                } else {
                    console.error('请求失败:', error);
                }
            }
        }
    }
}
</script>