<template>
    <div class="music-home">
        <el-autocomplete :fetch-suggestions="querySearch" :trigger-on-focus="false" placeholder="请输入内容" v-model="name"
            clearable>
            <el-button slot="append" @click="searchKey" icon="el-icon-search"></el-button>
        </el-autocomplete>

        <div id="aplayer">
            <pre class="aplayer-lrc-content"></pre>
        </div>

        <!-- 公告 -->
        <div class="marquee">
            <transition name="slide" mode="out-in">
                <div :key="currentTextIndex" class="text-item">
                    <div v-html="noticeTexts['notice'][currentTextIndex]"></div>
                </div>
            </transition>
        </div>

        <!-- <div class="fixed">固定头部</div> -->
        <el-tabs v-model="activeName" @tab-click="handleClick">
            <el-tab-pane label="最新" name="new"></el-tab-pane>
            <el-tab-pane label="最热" name="hot"></el-tab-pane>
            <!-- <el-tab-pane label="抖音" name="douyin"></el-tab-pane> -->
            <el-tab-pane label="DJ" name="dj"></el-tab-pane>
            <el-tab-pane label="播放列表" name="paylist"></el-tab-pane>
            <el-tab-pane label="关于" name="setup"></el-tab-pane>
        </el-tabs>

        <div ref="newScrollContainer" id="aplayer-list" class="fill newScrollContainer demo-image">
            <template v-if="['new', 'hot', 'douyin', 'dj'].includes(activeName)">
                <div class="block" v-for="(item, k) in kuwolist" :key="k">
                    <div class="listimg demo-image__lazy">
                        <el-image :src="transformedUrl(item.img)" @click="payList(item.id)" :fit="item.name"
                            lazy></el-image>
                    </div>

                    <span class="demonstration" @click="payList(item.id)">
                        {{ item.name }}
                    </span>
                </div>
                <div class="observer-element" ref="newBottomMarker">
                    {{ loadText }}
                </div>
                <el-backtop target=".newScrollContainer" :right="20" :bottom="100"></el-backtop>
            </template>
            <template v-if="activeName === 'paylist'">
                <li v-for="(item, k) in musicList" :key="k" :id="k === playIndex ? 'target-li' : ''">
                    <el-card shadow="hover">
                        <div class="mtitle">
                            <span class="fixedPlayico" v-if="k == playIndex">
                                <i class="el-icon-video-pause"></i>
                            </span>
                            <span v-else> {{ k + 1 }} - </span>
                            {{ item.title }}
                        </div>

                        <div class="pay">
                            <el-dropdown @command="handleCommand">
                                <span class="el-dropdown-link">
                                    <i class="el-icon-more-outline el-icon--right"></i>
                                </span>
                                <el-dropdown-menu slot="dropdown">
                                    <el-dropdown-item :command="{ action: 'play', k: k }">
                                        <i class="el-icon-video-pause"></i>播放
                                    </el-dropdown-item>
                                    <el-dropdown-item :command="{ action: 'next', k: k, data: item }">
                                        <i class="el-icon-video-play"></i>下一首播放
                                    </el-dropdown-item>
                                    <el-dropdown-item :command="{ action: 'del', k: k, data: item }">
                                        <i class="el-icon-delete"></i>删除
                                    </el-dropdown-item>
                                    <el-dropdown-item :command="{ action: 'download', rid: item.rid, type: 5 }">
                                        <i class="el-icon-download"></i>
                                        下载高品音质
                                    </el-dropdown-item>
                                    <el-dropdown-item :command="{ action: 'download', rid: item.rid, type: 6 }">
                                        <i class="el-icon-download"></i>
                                        下载无损音质
                                    </el-dropdown-item>
                                </el-dropdown-menu>
                            </el-dropdown>
                        </div>

                        <div class="author">
                            {{ item.author }}
                            <span>【{{ formatTime(item.duration) }}】</span>
                        </div>
                    </el-card>
                </li>

                <el-backtop target=".newScrollContainer" :right="60" :bottom="160"></el-backtop>
                <el-backtop target=".newScrollContainer" :right="60" :visibility-height="0" :bottom="50">
                    <i @click.stop="playfixed()" class="el-icon-location-information"></i>
                </el-backtop>
            </template>
            <template>
                <span v-show="activeName === 'setup'">
                    <div class="seting-group">
                        <p>
                            <span class="about">关于</span>
                        </p>

                        <p v-for="(item, k) in noticeTexts['sayings']" :key="k"> <span v-html="item"></span></p>

                    </div>
                    <div class="demo-image__placeholder">
                        <p>打赏</p>
                        <el-row>
                            <el-col v-for="(item, k) in noticeTexts['reward']" :key="k" :span="12">
                                <div class="grid-content bg-purple">
                                    <el-image :src="item"></el-image>
                                </div>
                            </el-col>
                        </el-row>
                    </div>
                </span>
            </template>

        </div>

        <el-drawer @opened="handleDrawerOpened" @closed="handleDrawerClosed" title="搜索结果" :visible.sync="drawer"
            :direction="direction" size="80%">
            <ul ref="serchScrollContainer" id="serchlist" class="scroll-serchContainer serchScrollContainer">

                <li v-for="(item, k) in addList" :key="k">
                    <el-card shadow="hover">
                        <div class="mtitle">{{ k + 1 }} - {{ item.title }}</div>

                        <div class="pay">
                            <el-dropdown @command="handleCommand">
                                <span class="el-dropdown-link">
                                    <i class="el-icon-more-outline el-icon--right"></i>
                                </span>
                                <el-dropdown-menu slot="dropdown">
                                    <el-dropdown-item :command="{ action: 'plays', k: k }">
                                        <i class="el-icon-video-play"></i>播放
                                    </el-dropdown-item>
                                    <el-dropdown-item :command="{ action: 'next', k: 9999, data: item }">
                                        <i class="el-icon-video-play"></i>下一首播放
                                    </el-dropdown-item>
                                    <el-dropdown-item :command="{ action: 'download', rid: item.rid, type: 5 }">
                                        <i class="el-icon-download"></i>
                                        下载高品音质
                                    </el-dropdown-item>
                                    <el-dropdown-item :command="{ action: 'download', rid: item.rid, type: 6 }">
                                        <i class="el-icon-download"></i>
                                        下载无损音质
                                    </el-dropdown-item>
                                </el-dropdown-menu>
                            </el-dropdown>
                        </div>

                        <div class="author">
                            {{ item.author }}
                            <span>【{{ formatTime(item.duration) }}】</span>
                        </div>

                    </el-card>
                </li>
                <div class="observer-element" ref="serchBottomMarker">
                    {{ loadText }}
                </div>
                <el-backtop target=".serchScrollContainer" :right="20" :bottom="100"></el-backtop>
            </ul>
        </el-drawer>
    </div>
</template>
<script>
import APlayer from "aplayer";
import "aplayer/dist/APlayer.min.css";
import request from "../server/request";

export default {
    data() {
        return {
            noticeTexts: {
                notice: [],
                sayings: [],
                reward:[],
            },
            currentTextIndex: 0,
            interval: null,
            
            fiexdTime: new Date(2025, 3, 25, 0, 30),
            deadline4: Date.now() + 1000 * 60 * 1,
            drawer: false,
            direction: "btt",
            activeIndex: 88888,
            name: "",
            kuwolist: [],
            netlist: [],
            musicList: [],
            addList: [],
            taglist: [],
            ap: "",
            activeName: "new",
            //基础url
            BASE_URL: "/music",
            //播放列表请求地址
            PLAY_URL: '/api/music',
            Notice_URL: '/notice',
            pn: 1,
            pns: 0,
            page: 0,
            limit: 30,
            serchType: '',
            playIndex: null, //播放歌曲索引
            observer: null,
            isLoading: false,
            isLoadings: false,
            observerSerch: null,
            playlistId: '',
            loadText: "数据努力加载中...",
        };
    },
    mounted() {
        this.getNotice();
        this.interval = setInterval(() => {
            this.currentTextIndex = (this.currentTextIndex + 1) % this.noticeTexts['notice'].length;
        }, 10000);
        this.timer = setInterval(() => {
            const data = request.getData(
                this.Notice_URL + "/ransay"
            );
            data.then((result) => {
                this.noticeTexts['sayings']['sayings'] = result;
            });

        }, 20000);
        this.initPlayer();
        this.dePay();
        //初始化分类标签数据例如：抖音专区，经典老歌专区 等。。。。
        //this.TagList();
        // 默认打开的是'new'标签页
        this.initObserver("newScrollContainer", "newBottomMarker");
    },

    beforeUnmount() {
        if (this.observer) {
            this.observer.disconnect();
        }
        if (this.observerSerch) {
            this.observerSerch.disconnect();
        }
        this.ap.destory(); //销毁播放器
    },
    computed: {
        shouldInitObserver() {
            return ["new", "hot", 'douyin', "dj"].includes(this.activeName);
        },
    },

    methods: {
        async getNotice() {
            const data = await request.getData(
                this.Notice_URL
            );
            this.noticeTexts = JSON.parse(data);
        },
        
        // 公共方法：替换图片 URL
        transformedUrl(originalUrl) {
            try {
                const url = new URL(originalUrl);
                const hostParts = url.hostname.split('.');
                // 检查是否符合 [前缀].[子域名].kuwo.cn 结构
                if (
                    hostParts.length >= 4 &&
                    hostParts[hostParts.length - 2] === 'kuwo' &&
                    hostParts[hostParts.length - 1] === 'cn'
                ) {
                    // 保留第一个前缀和最后两部分（kuwo.cn）
                    const newHost = `${hostParts[0]}.kuwo.cn`;
                    url.hostname = newHost;
                }
                return url.toString();
            } catch (e) {
                // 如果URL不合法，返回原URL
                return this.originalUrl;
            }
        },

        // 公共方法：处理分页加载逻辑
        updateListData(newData) {
            const isAllLoaded = newData.length === 0 || newData.length < this.limit;
            this.loadText = isAllLoaded ? "已加载完所有数据" : "数据努力加载中...";
            this.isLoading = isAllLoaded ? true : false;
            this.kuwolist.push(...newData);
        },
        // 公共错误处理方法
        handleError(error, context = '') {
            console.error(`[${context}] Error:`, error);
            this.$message.error('数据加载失败，请稍后重试');
        },

        //抽屉打开回调
        handleDrawerOpened() {
            this.$nextTick(() => {
                this.initObserverSerch("serchScrollContainer", "serchBottomMarker");
                //this.isLoadings = false;
                // 首次加载后自动滚动复位
                const ref = this.$refs.serchScrollContainer
                const container = ref?.$el?.querySelector('.scroll-container') || ref;
                if (container) container.scrollTop = 0
            });
        },
        // 抽屉关闭回调
        handleDrawerClosed() {
            this.pn = 1;
            this.pns = 0;
            this.addList = [];
            this.$nextTick(() => {
                this.initObserverSerch("serchScrollContainers", "serchBottomMarkers");
                // 首次加载后自动滚动复位
                const ref = this.$refs.serchScrollContainer
                const container = ref?.$el?.querySelector('.scroll-container') || ref;
                if (container) container.scrollTop = 0
            });
        },
        // 时间格式化
        formatTime(input, unit = 's') {
            let totalSeconds = unit === 'ms' ? input / 1000 : input;
            const mins = Math.floor(totalSeconds / 60);
            const secs = Math.floor(totalSeconds % 60);
            return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
        },
        // 播放菜单
        handleCommand(command) {
            const actions = {
                play: () => {
                    this.playNext(command.k);
                    this.playfixed();
                },
                plays: () => {
                    this.playSong(command.k);
                    this.playfixed();
                },
                next: () => {
                    const SPECIAL_CASE = 9999;
                    const audioData = command.data;
                    const currentIndex = this.ap.list.index;

                    // 创建索引映射表提升查找性能
                    const audioMap = new Map(
                        this.ap.list.audios.map((item, index) => [item.rid, index])
                    );

                    // 统一数组操作方法
                    const modifyList = (operations) => {
                        const newList = [...this.musicList];
                        operations.forEach(([start, deleteCount, ...items]) => {
                            newList.splice(start, deleteCount, ...items);
                        });
                        this.musicList = newList;
                        this.ap.list.audios = newList;
                    };

                    // 判断是否为新增歌曲
                    if (!audioMap.has(audioData.rid)) {
                        modifyList([
                            [command.k, 1], // 删除原位置
                            [currentIndex + 1, 0, audioData] // 插入新位置
                        ]);
                    } else {
                        // 处理移动逻辑
                        const sourceIndex = command.k === SPECIAL_CASE ? audioMap.get(audioData.rid) : command.k;

                        if (sourceIndex === currentIndex) return;

                        // 计算新位置和索引偏移
                        const insertPosition = sourceIndex < currentIndex
                            ? currentIndex
                            : currentIndex + 1;

                        const indexOffset = sourceIndex < currentIndex ? -1 : 0;

                        modifyList([
                            [sourceIndex, 1], // 删除原位置
                            [insertPosition, 0, audioData] // 插入新位置
                        ]);

                        // 更新播放索引
                        this.ap.list.index = currentIndex + indexOffset;
                        this.playIndex = this.ap.list.index;
                    }
                    this.$message({
                        message: '操作成功！',
                        type: 'success',
                        showClose: true,
                    });
                    //this.drawer = false;
                    //this.playfixed();
                },
                del: () => {
                    const currentIndex = this.ap.list.index;
                    const targetIndex = command.k;

                    // 创建新数组避免直接修改原始数据（提升响应式更新效率）
                    const newList = this.musicList.filter((_, idx) => idx !== targetIndex);

                    // 统一更新播放列表（减少重复操作）
                    this.$set(this, 'musicList', newList);
                    this.ap.list.audios = newList;

                    // 智能索引调整逻辑
                    let newPlayIndex = currentIndex;
                    if (targetIndex < currentIndex) {
                        newPlayIndex--;
                    } else if (targetIndex === currentIndex) {
                        // 删除当前歌曲时自动续播逻辑
                        newPlayIndex = Math.min(currentIndex, newList.length - 1);
                        if (newList.length > 0) {
                            //销毁播放
                            this.ap.destroy();
                            //重新初始化播放器，防止歌词不同步问题
                            this.initPlayer();
                            this.ap.list.switch(newPlayIndex);
                            this.ap.play(); // 立即触发播放状态同步
                        } else {
                            this.ap.pause(); // 列表为空时暂停
                        }
                    }

                    // 统一更新播放状态（避免多位置修改）
                    this.ap.list.index = newPlayIndex;
                    this.playIndex = newPlayIndex;
                },
                download: () => {
                    this.downloadMusic(command.rid, command.type);
                }
            };

            actions[command.action]?.();
        },
        //监听标签滚动事件，默认：最新
        initObserver(containerRef, markerRef) {
            // 销毁旧 Observer
            if (this.observer) {
                this.observer.disconnect();
                this.observer = null;
            }
            const scrollContainer = this.$refs[containerRef];
            const bottomMarker = this.$refs[markerRef];

            if (!scrollContainer || !bottomMarker) return;
            scrollContainer.scrollTop = 0
            // 创建观察器
            this.observer = new IntersectionObserver(
                ([entry]) => {
                    if (entry.isIntersecting && !this.isLoading) {
                        this.isLoading = true;
                        this.loadMoreData();
                    }
                },
                {
                    root: scrollContainer, // 指定滚动容器
                    threshold: 0.3, // 元素30%可见时触发
                }
            );
            // 开始观察底部标记元素
            this.observer.observe(bottomMarker);
        },

        //监听标签-搜索列表
        initObserverSerch(containerRef, markerRef) {
            // 销毁旧 Observer
            if (this.observerSerch) {
                this.observerSerch.disconnect();
                this.observerSerch = null;
            }
            const scrollContainer = this.$refs[containerRef];
            const bottomMarker = this.$refs[markerRef];

            if (!scrollContainer || !bottomMarker) return;

            // 创建观察器
            this.observerSerch = new IntersectionObserver(
                ([entrys]) => {
                    console.log(this.isLoadings)
                    if (entrys.isIntersecting && !this.isLoadings) {
                        this.isLoadings = true;
                        entrys.target.scrollIntoView({ behavior: 'smooth' });
                        this.loadMoreSerchData();
                    }
                },
                {
                    root: scrollContainer, // 指定滚动容器
                    threshold: 0.3, // 元素30%可见时触发
                }
            );
            // 开始观察底部标记元素
            this.observerSerch.observe(bottomMarker);
        },
        //定位播放歌曲
        playfixed() {
            setTimeout(() => {
                const container = document.getElementById("aplayer-list");
                const target = document.getElementById("target-li");
                if (container && target) {
                    // 直接使用scrollIntoView实现滚动（推荐）
                    target.scrollIntoView({
                        behavior: "smooth",
                        block: "center",    // 改为 center 使垂直居中
                        inline: "nearest"   // 保持水平方向自然对齐
                    });
                    // 兼容方案：手动计算中间位置
                    // const containerHeight = container.offsetHeight;
                    // const targetHeight = target.offsetHeight;
                    // const topPos = target.offsetTop - (containerHeight - targetHeight) / 2;
                    // container.scrollTop = topPos;
                }
            }, 100);
        },
        //初始化播放器
        initPlayer() {
            this.ap = new APlayer({
                container: document.getElementById("aplayer"),
                narrow: false,
                autoplay: false,
                showlrc: true,
                controls: true,
                theme: "#b7daff",
                loop: "all",
                //fixed:true,  //开启吸底模式
                lrcType: 3, // 可根据需要调整歌词类型
                volume: 0.7, //默认音量
                listFolded: true,
                audio: this.musicList,
            });

            this.ap.on("play", () => {
                this.playIndex = this.ap.list.index;
                //this.activeName = "paylist"; //切换到播放列表
                this.playfixed(); //定位到播放歌曲
                //console.log('当前播放时间' + this.ap.audio.currentTime);
            });
            this.ap.on("pause", () => {
                this.playIndex = null;
                //this.activeName = "paylist"; //切换到播放列表
                //this.playfixed(); //定位到播放歌曲
                //console.log('暂停' + this.ap.audio.currentTime);
            });
        },
        //标签切换
        handleClick(tab, event) {
            this.page = 0;
            this.kuwolist = [];
            this.loadText = "数据努力加载中...";

            setTimeout(() => {
                this.isLoading = false;
            }, 100);

            // 根据当前活动的标签页初始化对应的Observer
            if (this.shouldInitObserver) {
                this.$nextTick(() => this.initObserver("newScrollContainer", "newBottomMarker"));
            }
        },

        //下载音乐
        downloadMusic(id, type) {
            //const host = 'www.itmkk.com/api';
            const host = '';
            const url = this.PLAY_URL + "/downmusic?id=" + id + "&type=" + type;
            //let path = window.location.protocol + "//" + url;
            let path = window.location.origin + url;
            window.open(path);
        },
        //监听搜索关键词框联想事件
        querySearch(queryString, cb) {
            try {
                const data = request.getData(
                    this.BASE_URL + "/searchKey?name=" + this.name
                );
                data.then((result) => {
                    const resultArray = [];
                    result.forEach((item, index) => {
                        const endIndex = item.indexOf("\r\n");
                        const nrew = endIndex !== -1 ? item.substring(0, endIndex) : item;
                        const arrstr = nrew.substring("RELWORD=".length);
                        resultArray.push({ value: arrstr });
                    });
                    // 调用 callback 返回建议列表的数据
                    cb(resultArray);
                }).catch((error) => {
                    console.error("出现错误:", error);
                });
            } catch (error) {
                console.error("获取数据时出错:", error);
            }
        },

        //搜索结果
        async searchKey() {
            this.serchType = 'serch';
            //清除所有空格
            const key = this.name.replace(/\s+/g, "");
            if (!key) {
                this.$message.warning({
                    message: "请输入搜索关键字！！！",
                    showClose: true,
                });
                return false;
            }
            const loading = this.$loading({
                lock: true,
                text: "Loading",
                spinner: "el-icon-loading",
                background: "rgba(0, 0, 0, 0.7)",
            });
            try {
                const response = await request.getData(
                    `${this.BASE_URL}?name=${encodeURIComponent(key)}` +
                    `&pn=${this.pn}&rn=${this.limit}`
                );

                // 使用冻结对象优化性能
                const processedData = Object.freeze(response.abslist.map(this.serchMusicItem));

                // 批量更新数据（提升性能）
                this.addList.push(...processedData);

                loading.close();
                this.drawer = true;
                if (response.abslist.length === 0 || response.abslist.length < this.limit) {
                    this.loadText = "已加载完所有数据啦...";
                    this.isLoadings = true;//关闭监听滚动加载
                } else {
                    this.loadText = "数据努力加载中...";
                    setTimeout(() => {
                        this.isLoadings = false;
                    }, 500);
                }
            } catch (error) {
                this.handleError(error, '音乐搜索');
            } finally {
                this.loading = false;
                loading?.close();
            }
        },
        //切换播放歌曲
        playSong(item) {
            this.ap.list.clear();
            this.ap.list.add(this.addList);
            this.musicList = this.ap.list.audios;
            this.ap.list.switch(item); //切换到播放的歌曲
            setTimeout(() => this.ap.play(), 100); // 延迟重试
            this.ap.setMode("normal"); //播放器模式  'mini' 或 'normal'
            this.drawer = false; //关闭搜索结果
        },
        playNext(item) {
            this.ap.list.switch(item); //切换到播放的歌曲
            setTimeout(() => this.ap.play(), 100); // 延迟重试
        },
        //初始化分类列表数据
        async TagList() {
            try {
                const result = await request.getData(
                    `${this.BASE_URL}/taglist`
                );
                // 处理数据（冻结非响应式数据提升性能）
                this.taglist = result.data;

            } catch (error) {
                console.error("获取数据时出错:", error);
            }
        },
        //标签分类列表
        async TagListDatail(id) {
            try {
                const result = await request.getData(
                    `${this.BASE_URL}/tagplaylist?id=${id}&page=${this.page}&limit=${this.limit}`
                );
                // 批量更新数据
                this.updateListData(result.data);
            } catch (error) {
                console.error("获取数据时出错:", error);
            }
        },
        //初始播放列表数据
        async dePay() {
            try {
                const result = await request.getData(
                    `${this.BASE_URL}/songlist?id=2996314807`
                );
                // 处理数据（冻结非响应式数据提升性能）
                this.musicList = Object.freeze(result.map(this.kuwoListItem));
                // 批量添加播放列表
                this.ap.list.add([...this.musicList]);
            } catch (error) {
                console.error("获取数据时出错:", error);
