            const loading = this.$loading({
                lock: true,
                text: "Loading",
                spinner: "el-icon-loading",
                background: "rgba(0, 0, 0, 0.7)",
            });
            try {
                this.serchType = 'songlist';
                this.playlistId = id;

                const result = await request.getData(
                    `${this.BASE_URL}/songlist?id=${this.playlistId}` +
                    `&page=${this.pns}`
                );

                // 使用 push + 展开运算符提升性能
                const processedData = result.map(this.kuwoListItem);
                this.addList.push(...processedData);
                // 分页状态管理
                if (result.length === 0 || result.length < 100) {
                    this.loadText = "已加载完所有数据啦...";
                    this.isLoadings = true;//关闭监听滚动加载
                } else {
                    this.loadText = "数据努力加载中...";
                    this.isLoadings = false;
                }

                loading.close();
                this.drawer = true;

            } catch (error) {
                this.handleError(error, '加载歌单');
            } finally {
                this.loading = false;
                loading?.close();
