                    `?page=${this.page}&limit=${this.limit}&type=${this.activeName}`
                );

                // 批量更新数据
                this.updateListData(result.data);
            } catch (error) {
                this.handleError(error, '加载列表');
            } finally {
                this.isLoading = false;
