            const baseUrl = this.PLAY_URL;
            return {
                rid: item.id,
                title: item.name,
                name: item.name,
                artist: item.artist,
                author: item.artist,
                duration: item.duration,
                cover: `${baseUrl}/kwpic?id=${item.id}`,
                url: `${baseUrl}/kwurl?id=${item.id}`,
