                lrc: `${baseUrl}/kwlrc?id=${item.DC_TARGETID}`,
                _cached: Date.now() // 添加缓存标识
            };
        },
        //监听标签容器滚动加载数据
        loadMoreData() {
            // 数据加载完成后重置状态
            // 在 data 中定义映射表
            const activeNameMap = {
                dj: 168,
                douyin: 2189
            };
            // 调用逻辑优化为单行
            const param = activeNameMap[this.activeName];
            param ? this.TagListDatail(param) : this.Kwlist();
            this.page++;
        },
        //监听搜索结果容器滚动事件
        loadMoreSerchData() {
            // 数据加载完成后重置状态
            this.pn++;
            if (this.serchType == 'serch') {
                this.searchKey();
            }
            if (this.serchType == 'songlist') {
                this.pns++;
                this.payList(this.playlistId);
            }
        }
    },
};
